    font-size: 13px;
    outline: none;
  }
  select:focus, .text-input:focus { border-color: color-mix(in srgb, var(--accent-color) 55%, transparent); }
  .service-row select { flex: 1; min-width: 0; }
  option { background: #151515; }

  .add-btn {
    height: 32px;
    padding: 0 12px;
    display: inline-flex;
    align-items: center;
