    border: 1px solid color-mix(in srgb, var(--accent-color) 45%, transparent);
    background: color-mix(in srgb, var(--accent-color) 22%, transparent);
    color: var(--text-primary);
    font-size: 13px;
    font-weight: 500;
    white-space: nowrap;
    cursor: pointer;
    transition: all 0.2s ease;
  }
  .add-btn:hover:not(:disabled) { background: color-mix(in srgb, var(--accent-color) 35%, transparent); }
  .add-btn:disabled { opacity: 0.5; cursor: default; }
  .add-btn.ghost { background: rgba(255, 255, 255, 0.04); border-color: rgba(255, 255, 255, 0.1); }

  .custom-row {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin-top: var(--spacing-lg);
  }
  .text-input.name { width: 180px; }
  .text-input.url { flex: 1; min-width: 220px; }

  .source-list {
    list-style: none;
    margin: var(--spacing-lg) 0 0;
    padding: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;
  }
  .source-item {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 8px 8px 14px;
    border-radius: var(--border-radius-sm);
    background: rgba(255, 255, 255, 0.03);
  }
